"""Hash exact staged/installed artifact bytes, excluding generated bytecode."""

from __future__ import annotations

import hashlib
import zipfile
from pathlib import Path


def tree_digest(directory: Path) -> str:
    digest = hashlib.sha256()
    files = sorted(
        p
        for p in directory.rglob("*")
        if p.is_file() and "__pycache__" not in p.parts and p.suffix != ".pyc"
    )
    if not files:
        raise ValueError("empty_artifact_tree")
    for path in files:
        digest.update(path.relative_to(directory).as_posix().encode())
        digest.update(b"\0")
        digest.update(hashlib.sha256(path.read_bytes()).digest())
    return digest.hexdigest()


def file_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def wheel_package_digest(path: Path) -> str:
    digest = hashlib.sha256()
    with zipfile.ZipFile(path) as archive:
        names = sorted(
            n
            for n in archive.namelist()
            if n.startswith("ha_mcp/") and not n.endswith("/")
        )
        if not names:
            raise ValueError("wheel_package_absent")
        for name in names:
            digest.update(name.removeprefix("ha_mcp/").encode())
            digest.update(b"\0")
            digest.update(hashlib.sha256(archive.read(name)).digest())
    return digest.hexdigest()
